describe('Multiple Concurrent API Calls Resolution', () => {
  const apiBaseUrl = 'https://api.example.com';
  const dataContainerId = '[data-testid="data-container"]';
  const loadingSpinnerId = '[data-testid="loading-spinner"]';
  const errorMessageId = '[data-testid="error-message"]';

  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display data after all concurrent API calls resolve successfully', () => {
    // Intercept multiple API endpoints
    cy.intercept('GET', `${apiBaseUrl}/users`, {
      statusCode: 200,
      body: {
        data: [
          { id: 1, name: 'John Doe', email: 'john@example.com' },
          { id: 2, name: 'Jane Smith', email: 'jane@example.com' }
        ]
      },
      delay: 500
    }).as('getUsersCall');

    cy.intercept('GET', `${apiBaseUrl}/posts`, {
      statusCode: 200,
      body: {
        data: [
          { id: 1, title: 'First Post', userId: 1 },
          { id: 2, title: 'Second Post', userId: 2 }
        ]
      },
      delay: 800
    }).as('getPostsCall');

    cy.intercept('GET', `${apiBaseUrl}/comments`, {
      statusCode: 200,
      body: {
        data: [
          { id: 1, text: 'Great post!', postId: 1 },
          { id: 2, text: 'Thanks for sharing', postId: 2 }
        ]
      },
      delay: 600
    }).as('getCommentsCall');

    // Trigger the action that initiates concurrent API calls
    cy.get('[data-testid="load-data-button"]').click();

    // Verify loading state is visible
    cy.get(loadingSpinnerId).should('be.visible');

    // Wait for all API calls to complete
    cy.wait(['@getUsersCall', '@getPostsCall', '@getCommentsCall']);

    // Verify loading spinner is hidden
    cy.get(loadingSpinnerId).should('not.be.visible');

    // Verify data is displayed
    cy.get(dataContainerId).should('be.visible');
    cy.get(dataContainerId).should('contain', 'John Doe');
    cy.get(dataContainerId).should('contain', 'First Post');
    cy.get(dataContainerId).should('contain', 'Great post!');

    // Verify no error message is shown
    cy.get(errorMessageId).should('not.exist');
  });

  it('should handle partial API failure and display appropriate error message', () => {
    // Intercept successful API call
    cy.intercept('GET', `${apiBaseUrl}/users`, {
      statusCode: 200,
      body: {
        data: [{ id: 1, name: 'John Doe', email: 'john@example.com' }]
      },
      delay: 300
    }).as('getUsersCall');

    // Intercept failed API call
    cy.intercept('GET', `${apiBaseUrl}/posts`, {
      statusCode: 500,
      body: { error: 'Internal Server Error' },
      delay: 400
    }).as('getPostsCall');

    // Intercept another successful API call
    cy.intercept('GET', `${apiBaseUrl}/comments`, {
      statusCode: 200,
      body: {
        data: [{ id: 1, text: 'Great post!', postId: 1 }]
      },
      delay: 350
    }).as('getCommentsCall');

    // Trigger the action
    cy.get('[data-testid="load-data-button"]').click();

    // Verify loading state
    cy.get(loadingSpinnerId).should('be.visible');

    // Wait for all API calls to complete (including the failed one)
    cy.wait(['@getUsersCall', '@getPostsCall', '@getCommentsCall']);

    // Verify loading spinner is hidden
    cy.get(loadingSpinnerId).should('not.be.visible');

    // Verify error message is displayed
    cy.get(errorMessageId).should('be.visible');
    cy.get(errorMessageId).should('contain', 'Failed to load posts');

    // Verify partial data is still displayed
    cy.get(dataContainerId).should('contain', 'John Doe');
    cy.get(dataContainerId).should('contain', 'Great post!');

    // Verify failed data section shows error state
    cy.get('[data-testid="posts-section"]').should('contain', 'Error loading posts');
  });

  it('should retry failed concurrent API calls and display data on success', () => {
    let callCount = 0;

    // Intercept with dynamic response based on call count
    cy.intercept('GET', `${apiBaseUrl}/users`, {
      statusCode: 200,
      body: { data: [{ id: 1, name: 'John Doe' }] },
      delay: 200
    }).as('getUsersCall');

    cy.intercept('GET', `${apiBaseUrl}/posts`, (req) => {
      callCount++;
      if (callCount === 1) {
        req.reply({
          statusCode: 500,
          body: { error: 'Server Error' },
          delay: 300
        });
      } else {
        req.reply({
          statusCode: 200,
          body: { data: [{ id: 1, title: 'First Post' }] },
          delay: 300
        });
      }
    }).as('getPostsCall');

    cy.intercept('GET', `${apiBaseUrl}/comments`, {
      statusCode: 200,
      body: { data: [{ id: 1, text: 'Great post!' }] },
      delay: 250
    }).as('getCommentsCall');

    // Trigger initial load
    cy.get('[data-testid="load-data-button"]').click();
    cy.wait(['@getUsersCall', '@getPostsCall', '@getCommentsCall']);

    // Verify error is shown
    cy.get(errorMessageId).should('be.visible');

    // Click retry button
    cy.get('[data-testid="retry-button"]').click();

    // Wait for retry calls
    cy.wait(['@getUsersCall', '@getPostsCall', '@getCommentsCall']);

    // Verify error is cleared and data is displayed
    cy.get(errorMessageId).should('not.exist');
    cy.get(dataContainerId).should('be.visible');
    cy.get(dataContainerId).should('contain', 'First Post');
  });
});
